#include "ImageEngine.h"
#include <algorithm>
#include <cmath>
#include <cstring>

namespace picsay {
static inline uint8_t clamp8(float x){ return uint8_t(std::max(0.f,std::min(255.f,x))); }
static inline size_t at(const Image& i,int x,int y){ return (size_t(y)*i.width+x)*4; }
bool invert(Image& a){ if(!a.valid())return false; for(size_t p=0;p<a.rgba.size();p+=4)for(int c=0;c<3;c++)a.rgba[p+c]=255-a.rgba[p+c]; return true; }
bool grayscale(Image& a){ if(!a.valid())return false; for(size_t p=0;p<a.rgba.size();p+=4){auto y=clamp8(.2126f*a.rgba[p]+.7152f*a.rgba[p+1]+.0722f*a.rgba[p+2]);a.rgba[p]=a.rgba[p+1]=a.rgba[p+2]=y;}return true;}
bool adjust(Image& a,float b,float c,float s){if(!a.valid())return false;c=std::max(0.f,std::min(4.f,c));s=std::max(0.f,std::min(4.f,s));for(size_t p=0;p<a.rgba.size();p+=4){float r=a.rgba[p],g=a.rgba[p+1],bl=a.rgba[p+2],y=.2126f*r+.7152f*g+.0722f*bl;r=y+(r-y)*s;g=y+(g-y)*s;bl=y+(bl-y)*s; a.rgba[p]=clamp8((r-127.5f)*c+127.5f+b);a.rgba[p+1]=clamp8((g-127.5f)*c+127.5f+b);a.rgba[p+2]=clamp8((bl-127.5f)*c+127.5f+b);}return true;}
bool boxBlur(Image& a,int radius){if(!a.valid()||radius<0||radius>128)return false;if(!radius)return true;Image tmp=a;int w=a.width,h=a.height;for(int y=0;y<h;y++)for(int x=0;x<w;x++)for(int c=0;c<4;c++){int sum=0,n=0;for(int k=-radius;k<=radius;k++){int xx=std::max(0,std::min(w-1,x+k));sum+=tmp.rgba[at(tmp,xx,y)+c];n++;}a.rgba[at(a,x,y)+c]=uint8_t(sum/n);}tmp=a;for(int y=0;y<h;y++)for(int x=0;x<w;x++)for(int c=0;c<4;c++){int sum=0,n=0;for(int k=-radius;k<=radius;k++){int yy=std::max(0,std::min(h-1,y+k));sum+=tmp.rgba[at(tmp,x,yy)+c];n++;}a.rgba[at(a,x,y)+c]=uint8_t(sum/n);}return true;}
bool sharpen(Image& a,float amount){if(!a.valid())return false;Image blur=a;if(!boxBlur(blur,1))return false;amount=std::max(0.f,std::min(4.f,amount));for(size_t p=0;p<a.rgba.size();p+=4)for(int c=0;c<3;c++)a.rgba[p+c]=clamp8(a.rgba[p+c]+amount*(int(a.rgba[p+c])-int(blur.rgba[p+c])));return true;}
bool blend(Image& d,const Image& s,int ox,int oy,float opacity){if(!d.valid()||!s.valid())return false;opacity=std::max(0.f,std::min(1.f,opacity));for(int y=0;y<s.height;y++)for(int x=0;x<s.width;x++){int dx=x+ox,dy=y+oy;if(dx<0||dy<0||dx>=d.width||dy>=d.height)continue;size_t q=at(s,x,y),p=at(d,dx,dy);float sa=s.rgba[q+3]/255.f*opacity, da=d.rgba[p+3]/255.f, oa=sa+da*(1-sa);for(int c=0;c<3;c++)d.rgba[p+c]=oa>0?clamp8((s.rgba[q+c]*sa+d.rgba[p+c]*da*(1-sa))/oa):0;d.rgba[p+3]=clamp8(oa*255);}return true;}
bool crop(const Image& a,int x,int y,int w,int h,Image& o){if(!a.valid()||w<=0||h<=0||x<0||y<0||x+w>a.width||y+h>a.height)return false;o.width=w;o.height=h;o.rgba.resize(size_t(w)*h*4);for(int j=0;j<h;j++)std::memcpy(&o.rgba[size_t(j)*w*4],&a.rgba[at(a,x,y+j)],size_t(w)*4);return true;}
bool rotate90(const Image& a,int turns,Image& o){if(!a.valid())return false;turns=((turns%4)+4)%4;if(turns%2){o.width=a.height;o.height=a.width;}else{o.width=a.width;o.height=a.height;}o.rgba.resize(a.rgba.size());for(int y=0;y<a.height;y++)for(int x=0;x<a.width;x++){int dx=x,dy=y;if(turns==1){dx=a.height-1-y;dy=x;}else if(turns==2){dx=a.width-1-x;dy=a.height-1-y;}else if(turns==3){dx=y;dy=a.width-1-x;}std::memcpy(&o.rgba[at(o,dx,dy)],&a.rgba[at(a,x,y)],4);}return true;}
bool pixelize(Image& a,int block){if(!a.valid()||block<1||block>512)return false;for(int y=0;y<a.height;y+=block)for(int x=0;x<a.width;x+=block){uint64_t sums[4]={};int n=0;for(int yy=y;yy<std::min(y+block,a.height);yy++)for(int xx=x;xx<std::min(x+block,a.width);xx++){size_t p=at(a,xx,yy);for(int c=0;c<4;c++)sums[c]+=a.rgba[p+c];n++;}for(int yy=y;yy<std::min(y+block,a.height);yy++)for(int xx=x;xx<std::min(x+block,a.width);xx++){size_t p=at(a,xx,yy);for(int c=0;c<4;c++)a.rgba[p+c]=uint8_t(sums[c]/n);}}return true;}
bool warpBulge(Image& a,float cx,float cy,float radius,float strength){if(!a.valid()||radius<=0)return false;Image src=a;float r2=radius*radius;for(int y=0;y<a.height;y++)for(int x=0;x<a.width;x++){float dx=x-cx,dy=y-cy,d2=dx*dx+dy*dy;if(d2>=r2)continue;float d=std::sqrt(d2),f=1.f+strength*(1.f-d/radius)*(1.f-d/radius);int sx=std::max(0,std::min(a.width-1,int(std::round(cx+dx*f)))),sy=std::max(0,std::min(a.height-1,int(std::round(cy+dy*f))));std::memcpy(&a.rgba[at(a,x,y)],&src.rgba[at(src,sx,sy)],4);}return true;}
}
